const updateClusterBerVersion = `-- name: UpdateClusterBerVersion :many
UPDATE core_cluster SET
  code = $1,
  nama = $2,
  deskripsi = $3,
  icon = $4,
  tone = $5,
  urutan = $6,
  status = $7,
  version = $8,
  updated_at = $9::timestamptz
WHERE id = $10::bigint
  AND version = $11
  AND deleted_at IS NULL
RETURNING id, entity_id, code, nama, deskripsi, icon, tone, urutan, status, version, created_at, updated_at, deleted_at
`

type UpdateClusterBerVersionParams struct {
	Code        string             `json:"code"`
	Nama        string             `json:"nama"`
	Deskripsi   pgtype.Text        `json:"deskripsi"`
	Icon        pgtype.Text        `json:"icon"`
	Tone        pgtype.Text        `json:"tone"`
	Urutan      int32              `json:"urutan"`
	Status      EnumStatusAktif    `json:"status"`
	Version     int32              `json:"version"`
	UpdatedAt   pgtype.Timestamptz `json:"updated_at"`
	ID          int64              `json:"id"`
	VersiServer int32              `json:"versi_server"`
}

// Patch ber-version (optimistic lock) — kosong = version berubah di antara
// baca & tulis (race — 409 SYS-409 di service).
func (q *Queries) UpdateClusterBerVersion(ctx context.Context, arg UpdateClusterBerVersionParams) ([]CoreCluster, error) {
	rows, err := q.db.Query(ctx, updateClusterBerVersion,
		arg.Code,
		arg.Nama,
		arg.Deskripsi,
		arg.Icon,
		arg.Tone,
		arg.Urutan,
		arg.Status,
		arg.Version,
		arg.UpdatedAt,
		arg.ID,
		arg.VersiServer,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []CoreCluster
	for rows.Next() {
		var i CoreCluster
		if err := rows.Scan(
			&i.ID,
			&i.EntityID,
			&i.Code,
			&i.Nama,
			&i.Deskripsi,
			&i.Icon,
			&i.Tone,
			&i.Urutan,
			&i.Status,
			&i.Version,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.DeletedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
